"""Self-contained visual review for imported RomanText source annotations."""

from __future__ import annotations

import html
import json
from pathlib import Path
from typing import Any


REVIEW_VERSION = "romantext-review-0.4.0"


def write_romantext_review_html(package: dict[str, Any], pages: list[str], destination: str | Path) -> Path:
    destination = Path(destination)
    destination.parent.mkdir(parents=True, exist_ok=True)
    payload = json.dumps(package, ensure_ascii=False).replace("</", "<\\/")
    engraved = "".join(f'<section class="page">{page}</section>' for page in pages)
    title = html.escape(package["ir"]["score"].get("title") or "RomanText Review")
    page = f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>{title} · RomanText Review</title><style>
:root{{--bg:#eef1f5;--paper:#fffef8;--ink:#17202a;--muted:#687180;--blue:#2563eb;--amber:#d97706;--red:#b91c1c}}
*{{box-sizing:border-box}}body{{margin:0;font:14px/1.45 system-ui,sans-serif;background:var(--bg);color:var(--ink)}}
header{{height:58px;background:#101820;color:white;display:flex;align-items:center;justify-content:space-between;padding:0 18px}}
.layout{{display:grid;grid-template-columns:minmax(680px,1fr) 390px;height:calc(100vh - 58px)}}.left{{overflow:auto;padding:14px}}.paper{{position:relative;background:var(--paper);padding:16px;min-height:700px;box-shadow:0 2px 8px #0002}}
.page{{position:relative;max-width:1150px;margin:0 auto 18px;border-bottom:1px solid #ddd}}.page svg{{display:block;width:100%;height:auto}}
.side{{overflow:auto;background:white;border-left:1px solid #d8dce3;padding:16px}}.toolbar{{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px}}input,select{{padding:7px;border:1px solid #cbd5e1;border-radius:6px}}
.item{{display:block;width:100%;text-align:left;border:1px solid #dbe2ea;background:white;border-radius:7px;padding:8px;margin:6px 0;cursor:pointer}}.item:hover,.item.selected{{border-color:var(--blue);background:#eff6ff}}.item.ambiguous{{border-color:#fecaca;background:#fff7f7}}.meta{{font-size:11px;color:var(--muted)}}
.overlay{{position:absolute;z-index:7;transform:translateY(-100%);padding:2px 6px;border:1px solid var(--amber);border-radius:5px;background:#fff7d6e8;color:#713f12;font-weight:700;font-size:11px;cursor:pointer;white-space:nowrap;box-shadow:0 1px 3px #0002}}.overlay.flash{{animation:flash 1s ease}}@keyframes flash{{0%,100%{{background:#fff7d6e8}}50%{{background:#fde047;outline:4px solid #f59e0b55}}}}
.legend{{display:flex;gap:8px;align-items:center;font-size:11px;color:var(--muted)}}.swatch{{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:3px;vertical-align:-1px}}.swatch.range{{background:#fbbf24}}.swatch.start{{background:#16a34a}}.swatch.end{{background:#dc2626}}
.card{{border:1px solid #dde2e8;border-radius:8px;padding:10px;margin:8px 0}}.k{{font-size:10px;text-transform:uppercase;color:var(--muted)}}code{{font-size:11px;word-break:break-all}}.badge{{padding:3px 8px;border-radius:999px;background:#dcfce7;color:#166534;font-size:11px}}.warn{{background:#fee2e2;color:#991b1b}}.review-box select,.review-box textarea,.review-box button,.case-box select,.case-box textarea,.case-box button{{width:100%;margin-top:6px;padding:7px;border:1px solid #cbd5e1;border-radius:6px;font:inherit}}.review-box textarea,.case-box textarea{{min-height:64px;resize:vertical}}.review-box button,.case-box button{{background:#2563eb;color:white;border:0;cursor:pointer}}.case-box{{border:1px solid #c4b5fd;background:#faf8ff;border-radius:8px;padding:9px;margin-top:8px}}.case-head{{display:flex;justify-content:space-between;gap:8px}}.case-score{{font-weight:700;color:#6d28d9}}.case-actions{{display:grid;grid-template-columns:1fr 1fr;gap:6px}}.case-actions .secondary{{background:#fff;color:#4338ca;border:1px solid #a5b4fc}}.axis-grid{{display:grid;grid-template-columns:1fr 1fr;gap:4px}}.axis-grid label{{font-size:11px}}.review-saved{{color:#166534;font-size:11px;margin-top:5px}}g.note[data-id^="note_"]{{cursor:pointer}}g.note.harmony-span .notehead{{fill:#fbbf24!important;color:#fbbf24!important}}g.note.harmony-start .notehead{{fill:#16a34a!important;color:#16a34a!important;stroke:#14532d!important;stroke-width:12px!important}}g.note.harmony-end .notehead{{fill:#dc2626!important;color:#dc2626!important;stroke:#7f1d1d!important;stroke-width:12px!important}}g.note.harmony-start.harmony-end .notehead{{fill:#7c3aed!important;color:#7c3aed!important;stroke:#4c1d95!important}}g.note.focus .notehead{{filter:drop-shadow(0 0 5px #2563eb)}}
@media(max-width:900px){{.layout{{grid-template-columns:1fr;height:auto}}.side{{border-left:0;border-top:1px solid #ddd}}}}
</style></head><body><header><strong>MUSICANOTE · RomanText Source Review</strong><span><span class="badge">source annotation</span> <span class="badge warn">not gold</span></span></header>
<div class="layout"><main class="left"><div class="paper"><div class="toolbar"><strong>{title}</strong><label><input id="showOverlay" type="checkbox" checked> 악보 위 화성 구간</label><span id="summary"></span><span class="legend"><span><i class="swatch range"></i>지속</span><span><i class="swatch start"></i>시작</span><span><i class="swatch end"></i>마지막 attack</span></span></div><div id="score">{engraved}</div></div></main>
<aside class="side"><div class="toolbar"><input id="query" placeholder="화음·조성·마디 검색"><select id="status"><option value="all">전체</option><option value="exact">exact</option><option value="ambiguous">ambiguous</option></select></div><div id="detail"></div><h3>화성 목록</h3><div id="list"></div></aside></div>
<script id="payload" type="application/json">{payload}</script><script>
const D=JSON.parse(document.getElementById('payload').textContent),ir=D.ir,A=D.annotations,L=D.alignments,E=D.source_evidence?.records||[],C=D.context_evidence?.records||[],byAnn=Object.fromEntries(L.map(x=>[x.annotation_id,x])),byEv=Object.fromEntries(E.map(x=>[x.annotation_id,x])),byCx=Object.fromEntries(C.map(x=>[x.annotation_id,x])),sounds=Object.fromEntries(ir.sounding_events.map(x=>[x.sounding_event_id,x]));
const reviewId=(location.pathname.match(new RegExp('^/reviews/([0-9a-f]{{16}})/'))||[])[1]||'',reasonLabels={{surface_compatible:'표면 악보와 호환',non_chord_tone:'비화성음/장식음 가능성',inversion_or_bass:'전위/베이스 해석',local_key_or_tonicization:'국소 조성/일시적 으뜸화',alignment_or_timeline:'정렬/시간축 문제',source_label_suspect:'원자료 라벨 의심',cannot_judge:'판단 보류'}},caseVerdicts={{useful_analogy:'유용한 유사 사례',similar_surface_different_function:'표면은 비슷하지만 기능은 다름',not_similar:'유사하지 않음',cannot_judge:'판단 불가'}},caseAxes={{surface:'표면',bass_motion:'베이스',voice_leading:'성부진행',harmonic_function:'화성 기능',nct_context:'NCT 문맥',phrase_role:'프레이즈 역할'}};let reviewer={{}},activeAnnotation=null,caseCache={{}};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));
const cards=rows=>rows.map(([k,v])=>`<div class="card"><div class="k">${{esc(k)}}</div><div>${{v}}</div></div>`).join('');
const q=r=>r?Number(r.numerator)/Number(r.denominator):0;
function boundary(a){{const l=byAnn[a.annotation_id],att=(l.attacked_sounding_event_ids||[]).map(id=>sounds[id]).filter(Boolean).sort((x,y)=>q(x.span.start)-q(y.span.start));if(!att.length)return {{start:[],end:[],all:[]}};const lo=q(att[0].span.start),hi=q(att[att.length-1].span.start);return {{start:att.filter(x=>q(x.span.start)===lo),end:att.filter(x=>q(x.span.start)===hi),all:(l.sounding_event_ids||[]).map(id=>sounds[id]).filter(Boolean)}}}}
function pitches(xs){{return [...new Set(xs.map(x=>x.pitch?.spelling).filter(Boolean))].join(', ')||'unknown'}}
const pct=x=>x==null?'unknown':`${{(100*x).toFixed(1)}}%`;
function evidenceText(e){{if(!e||e.status!=='scored')return '평가 불가';return `${{esc(e.support_band)}}<br>기대 구성음 출현 ${{pct(e.expected_tone_presence_ratio)}} · 구간 음가 중 화음 구성음 ${{pct(e.chord_tone_duration_ratio)}} · attack 기준 ${{pct(e.attack_chord_tone_duration_ratio)}}<br>기대 구성음 [${{esc((e.expected_pitch_spellings||[]).join(', '))}}] (PC ${{e.expected_pitch_classes.join(', ')}})<br>누락 PC [${{e.missing_expected_pitch_classes.join(', ')||'없음'}}] · 외부 PC [${{e.foreign_pitch_classes.join(', ')||'없음'}}]<br>시작 베이스/기대 베이스 PC: ${{e.observed_bass_pitch_class_at_start??'unknown'}} / ${{e.expected_bass_pitch_class}} (${{esc(e.expected_bass_spelling||'')}}; ${{e.bass_matches_notated_inversion===true?'일치':e.bass_matches_notated_inversion===false?'불일치':'판정 불가'}})<br><span class="meta">이 등급은 악보 표면과의 호환 증거이며 화성 정답률이나 confidence가 아닙니다.</span>`}}
function contextText(c){{if(!c)return '평가 자료 없음';if(c.status!=='scored')return `${{esc(c.status)}} · ${{esc((c.diagnostics||[]).join(', '))}}`;const edges=c.boundary_voice_leading_edges||[],res=edges.filter(x=>x.possible_nct_resolution).map(x=>`${{x.from_midi}}→${{x.to_midi}} (${{x.interval_semitones>0?'+':''}}${{x.interval_semitones}})`);return `진행: ${{esc(c.previous_raw_label||'시작')}} → <strong>${{esc(c.raw_label)}}</strong> → ${{esc(c.next_raw_label||'끝')}}<br>다음 화음과 공통 기대 PC [${{(c.expected_pitch_class_overlap_with_next||[]).join(', ')||'없음'}}] · 새 기대 PC [${{(c.expected_pitch_class_change_to_next||[]).join(', ')||'없음'}}]<br>실제 시작 bass 이동: ${{c.observed_bass_motion_semitones==null?'unknown':`${{c.observed_bass_motion_semitones>0?'+':''}}${{c.observed_bass_motion_semitones}} semitones`}}<br>성부 연결 ${{edges.length}}개 · 순차 진행 ${{c.stepwise_edge_count}}개 · NCT 해결 후보 ${{c.possible_nct_resolution_count}}개${{res.length?` (${{res.join(', ')}})`:''}}<br><span class="meta">전후 경계의 기술적 증거이며 기능화성 정답이나 NCT 확정 판정이 아닙니다.</span>`}}
function reviewEditor(a){{if(!reviewId)return '<span class="meta">카탈로그 서버에서 열면 검토 결과를 저장할 수 있습니다.</span>';const r=reviewer[a.annotation_id]||{{}},options=Object.entries(reasonLabels).map(([v,t])=>`<option value="${{v}}" ${{r.reason===v?'selected':''}}>${{t}}</option>`).join('');return `<div class="review-box"><select id="reviewReason"><option value="">분류 선택</option>${{options}}</select><textarea id="reviewNote" placeholder="판단 근거 또는 수정 의견(선택)">${{esc(r.note||'')}}</textarea><button onclick="saveReview()">검토 저장</button>${{r.created_at?`<div class="review-saved">저장됨 · ${{esc(reasonLabels[r.reason]||r.reason)}} · ${{esc(r.created_at)}}</div>`:''}}<div class="meta">이 기록은 triage 검토이며 별도 adjudication 전에는 학습 정답이 아닙니다.</div></div>`}}
const ratingOptions=v=>`<option value="">선택 안 함</option>${{[0,1,2,3,4].map(x=>`<option value="${{x}}" ${{String(v)===String(x)?'selected':''}}>${{x}}</option>`).join('')}}`;
function casePanel(a){{const l=byAnn[a.annotation_id];if(!reviewId)return '<span class="meta">카탈로그 서버에서만 사례 검색을 사용할 수 있습니다.</span>';if(l.mapping_status!=='exact')return '<span class="meta">exact 구간만 검색할 수 있습니다.</span>';const s=caseCache[a.annotation_id];if(!s)return `<button onclick="loadHarmonyCases('${{a.annotation_id}}')">다른 작품의 유사 사례 찾기</button><div class="meta">train 사례만 검색하며 결과는 정답이 아닙니다.</div>`;if(s.loading)return '검색 중…';if(s.error)return `<span class="warn">${{esc(s.error)}}</span><button onclick="loadHarmonyCases('${{a.annotation_id}}')">다시 시도</button>`;const qid=s.query.query_id,engine=s.engine_version;return `<div class="meta">${{s.matches.length}}건 · ${{esc(engine)}} · 구조 분석 영향 없음</div>`+s.matches.map(m=>{{const id=m.case_id,r=s.reviews?.[id]||{{}},axes=Object.entries(caseAxes).map(([axis,label])=>`<label>${{label}}<select id="axis_${{id}}_${{axis}}">${{ratingOptions(r.axis_ratings?.[axis])}}</select></label>`).join(''),verdicts=Object.entries(caseVerdicts).map(([value,label])=>`<option value="${{value}}" ${{r.verdict===value?'selected':''}}>${{label}}</option>`).join('');return `<div class="case-box"><div class="case-head"><span><strong>${{esc(m.label.raw)}}</strong> · ${{esc(m.label.taxonomy?.family||'unresolved')}}</span><span class="case-score">${{(100*m.comparison.similarity).toFixed(1)}}%</span></div><div class="meta">유사: ${{esc((m.comparison.similar_reasons||[]).join(', '))}}<br>차이: ${{esc((m.comparison.difference_reasons||[]).join(', ')||'뚜렷한 차이 없음')}}<br>${{esc(m.dataset_identity?.collection_id||'')}} · source evidence ${{esc(m.source_evidence?.support_band||'unscorable')}}</div><div class="case-actions"><button class="secondary" onclick="openCaseContext('${{id}}')">후보 악보 열기</button><select id="verdict_${{id}}"><option value="">평가 선택</option>${{verdicts}}</select></div><details><summary>평가 축 0–4 (선택)</summary><div class="axis-grid">${{axes}}</div></details><textarea id="caseNote_${{id}}" placeholder="왜 비슷하거나 다른지 기록(선택)">${{esc(r.note||'')}}</textarea><button onclick="saveCaseFeedback('${{a.annotation_id}}','${{qid}}','${{id}}','${{engine}}')">사례 피드백 저장</button>${{r.created_at?`<div class="review-saved">저장됨 · ${{esc(caseVerdicts[r.verdict]||r.verdict)}}</div>`:''}}</div>`}}).join('')+`<div class="meta">피드백은 append-only로 저장되며 adjudication과 dev/holdout 검증 전에는 순위나 규칙을 바꾸지 않습니다.</div>`}}
function show(a,button){{activeAnnotation=a;document.querySelectorAll('.item.selected').forEach(x=>x.classList.remove('selected'));button?.classList.add('selected');const l=byAnn[a.annotation_id],e=byEv[a.annotation_id],c=byCx[a.annotation_id],target=a.target?.span,b=boundary(a);document.getElementById('detail').innerHTML=`<h2>${{esc(a.raw_label)}}</h2>`+cards([['상태',l.mapping_status],['조성',esc(a.components.key)],['악보 위치',`m.${{esc(a.native_target.measure)}} · onset ${{esc(a.native_target.local_onset_quarter)}} · duration ${{esc(a.native_target.duration_quarter)}}`],['화성 구간',`시작 attack: ${{esc(pitches(b.start))}}<br>마지막 attack: ${{esc(pitches(b.end))}}<br><span class="meta">끝 좌표는 다음 화음이 시작하는 시점이며 그 좌표 자체는 포함하지 않습니다. 황색 음표는 시간 범위 표시이며, 모두 화음 구성음이라는 뜻은 아닙니다.</span>`],['악보 호환 증거',evidenceText(e)],['전후 진행·해결 증거',contextText(c)],['검토 분류',reviewEditor(a)],['유사 화성 사례',casePanel(a)],['IR 구간',target?`${{target.start.numerator}}/${{target.start.denominator}} – ${{target.end.numerator}}/${{target.end.denominator}} quarter · [start,end)`:'연결 안 됨'],['원문',`<code>${{esc(a.source_locator.path)}}:${{a.source_locator.line}}</code>`],['출처 등급',`${{esc(a.author_origin)}} · ${{esc(a.source_review_status)}}`],['진단',l.diagnostics.map(esc).join(', ')||'없음'],['주의','이 라벨은 가져온 원자료이며 Harness의 독립 예측이나 사람 정답이 아닙니다.']]);focus(a)}}
async function loadHarmonyCases(annotationId){{caseCache[annotationId]={{loading:true}};show(activeAnnotation,document.querySelector(`.item[data-ann="${{annotationId}}"]`));try{{const r=await fetch(`/api/harmony-cases/${{reviewId}}?annotation_id=${{encodeURIComponent(annotationId)}}&limit=6`),d=await r.json();if(!r.ok)throw new Error(d.error||'검색 실패');caseCache[annotationId]=d}}catch(e){{caseCache[annotationId]={{error:e.message}}}}show(activeAnnotation,document.querySelector(`.item[data-ann="${{annotationId}}"]`))}}
async function saveCaseFeedback(annotationId,queryId,caseId,engineVersion){{const verdict=document.getElementById(`verdict_${{caseId}}`).value;if(!verdict){{alert('사례 평가를 선택하세요.');return}}const axis_ratings={{}};for(const axis of Object.keys(caseAxes)){{const value=document.getElementById(`axis_${{caseId}}_${{axis}}`).value;if(value!=='')axis_ratings[axis]=Number(value)}}const note=document.getElementById(`caseNote_${{caseId}}`).value,r=await fetch(`/api/harmony-case-reviews/${{reviewId}}`,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{annotation_id:annotationId,query_id:queryId,case_id:caseId,engine_version:engineVersion,verdict,axis_ratings,note}})}}),d=await r.json();if(!r.ok){{alert(d.error||'저장 실패');return}}caseCache[annotationId].reviews??={{}};caseCache[annotationId].reviews[caseId]=d;show(activeAnnotation,document.querySelector(`.item[data-ann="${{annotationId}}"]`))}}
async function openCaseContext(caseId){{const r=await fetch('/api/harmony-case-context',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{case_id:caseId}})}}),d=await r.json();if(!r.ok){{alert(d.error||'후보 악보 생성 실패');return}}window.open(d.url,'_blank')}}
async function loadReviews(){{if(!reviewId)return;try{{const r=await fetch(`/api/reviews/${{reviewId}}`),d=await r.json();if(r.ok)reviewer=d.reviews||{{}}}}catch(_e){{}}}}
async function saveReview(){{if(!activeAnnotation||!reviewId)return;const reason=document.getElementById('reviewReason').value,note=document.getElementById('reviewNote').value;if(!reason){{alert('검토 분류를 선택하세요.');return}}const r=await fetch(`/api/reviews/${{reviewId}}`,{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{annotation_id:activeAnnotation.annotation_id,reason,note}})}}),d=await r.json();if(!r.ok){{alert(d.error||'저장 실패');return}}reviewer[activeAnnotation.annotation_id]=d;show(activeAnnotation,document.querySelector(`.item[data-ann="${{activeAnnotation.annotation_id}}"]`))}}
function anchor(a){{const l=byAnn[a.annotation_id],ids=[...(l.attacked_sounding_event_ids||[]),...(l.sounding_event_ids||[])];for(const sid of ids){{for(const nid of (sounds[sid]?.source_note_ids||[])){{const g=document.querySelector(`g.note[data-id="${{nid}}"]`);if(g)return g}}}}return null}}
function noteGroups(xs){{const out=[];for(const s of xs)for(const nid of (s.source_note_ids||[])){{const g=document.querySelector(`g.note[data-id="${{nid}}"]`);if(g&&!out.includes(g))out.push(g)}}return out}}
function clearRange(){{document.querySelectorAll('g.note.harmony-span,g.note.harmony-start,g.note.harmony-end,g.note.focus').forEach(x=>x.classList.remove('harmony-span','harmony-start','harmony-end','focus'))}}
function focus(a){{clearRange();const b=boundary(a),all=noteGroups(b.all),starts=noteGroups(b.start),ends=noteGroups(b.end);all.forEach(x=>x.classList.add('harmony-span'));starts.forEach(x=>x.classList.add('harmony-start'));ends.forEach(x=>x.classList.add('harmony-end'));const g=starts[0]||anchor(a);if(!g)return;g.classList.add('focus');g.scrollIntoView({{behavior:'smooth',block:'center'}});const o=document.querySelector(`.overlay[data-ann="${{a.annotation_id}}"]`);if(o){{o.classList.remove('flash');void o.offsetWidth;o.classList.add('flash')}}}}
function overlays(){{document.querySelectorAll('.overlay').forEach(x=>x.remove());if(!document.getElementById('showOverlay').checked){{clearRange();return}}const root=document.getElementById('score'),rb=root.getBoundingClientRect();A.filter(a=>byAnn[a.annotation_id].mapping_status==='exact').forEach(a=>{{const g=anchor(a);if(!g)return;const b=g.getBoundingClientRect(),o=document.createElement('button');o.className='overlay';o.dataset.ann=a.annotation_id;o.textContent=`${{a.raw_label}} · 구간`;o.style.left=`${{b.left-rb.left}}px`;o.style.top=`${{b.top-rb.top-4}}px`;o.onclick=()=>show(a,document.querySelector(`.item[data-ann="${{a.annotation_id}}"]`));root.append(o)}})}}
function renderList(){{const q=document.getElementById('query').value.toLowerCase(),s=document.getElementById('status').value,list=document.getElementById('list');list.replaceChildren();A.forEach(a=>{{const l=byAnn[a.annotation_id],e=byEv[a.annotation_id],ok=s==='all'||l.mapping_status===s,hay=`${{a.raw_label}} ${{a.components.key}} ${{a.native_target.measure}} ${{e?.support_band||''}}`.toLowerCase();if(!ok||!hay.includes(q))return;const b=document.createElement('button');b.className='item '+(l.mapping_status==='ambiguous'?'ambiguous':'');b.dataset.ann=a.annotation_id;b.innerHTML=`<strong>${{esc(a.raw_label)}}</strong> · ${{esc(a.components.key)}}<div class="meta">m.${{esc(a.native_target.measure)}} · ${{l.mapping_status}} · ${{esc(e?.support_band||'unscored')}} · line ${{a.source_locator.line}}</div>`;b.onclick=()=>show(a,b);list.append(b)}})}}
document.getElementById('summary').textContent=`${{D.report.exact_alignments}} exact · ${{D.report.ambiguous_alignments}} ambiguous`;document.getElementById('query').oninput=renderList;document.getElementById('status').onchange=renderList;document.getElementById('showOverlay').onchange=overlays;window.addEventListener('resize',()=>requestAnimationFrame(overlays));loadReviews().then(()=>{{renderList();requestAnimationFrame(overlays)}});document.getElementById('detail').innerHTML=cards([['Track',`<code>${{esc(D.report.annotation_track_id)}}</code>`],['정책',esc(D.report.annotation_input_policy)],['안내','목록이나 악보 위 로마숫자를 누르면 화성이 유지되는 전체 구간과 시작·마지막 attack을 확인할 수 있습니다.']]);
</script></body></html>'''
